class ContractDocumentKind(str, Enum):
    CONTRATO = "CONTRATO"
    AVISO_PRIVACIDAD = "AVISO_PRIVACIDAD"
    CONSENTIMIENTO = "CONSENTIMIENTO"
    RECIBO = "RECIBO"
    AUTORIZACION = "AUTORIZACION"
    ANEXO = "ANEXO"
    OTRO = "OTRO"


class DocumentAcceptanceKind(str, Enum):
    ACEPTACION = "ACEPTACION"
    CONSENTIMIENTO = "CONSENTIMIENTO"
    FIRMA_EXTERNA = "FIRMA_EXTERNA"
    ACUSE = "ACUSE"


@dataclass(frozen=True)
class ContractDocumentVersion:
    document_version_id: str
    contract_id: str
    contract_period_id: Optional[str]
    kind: ContractDocumentKind
    version_label: str
    document_reference: str
    effective_from: str
    effective_to: Optional[str] = None
    supersedes_document_version_id: Optional[str] = None


@dataclass(frozen=True)
class DocumentAcceptanceEvidence:
    acceptance_id: str
    document_version_id: str
    acceptance_kind: DocumentAcceptanceKind
    actor_reference: str
    accepted_at: str
    evidence_reference: str
    provider_reference: Optional[str] = None
    revoked_at: Optional[str] = None
    revocation_reason: Optional[str] = None


def validate_contract_document_version(document: ContractDocumentVersion) -> None:
    for field_name, value in (("document_version_id", document.document_version_id), ("contract_id", document.contract_id), ("version_label", document.version_label), ("document_reference", document.document_reference), ("effective_from", document.effective_from)):
        if not str(value or "").strip():
            raise ValueError(f"ContractDocumentVersion requiere {field_name}")
    if document.effective_to and document.effective_to < document.effective_from:
        raise ValueError("effective_to no puede ser anterior a effective_from")
    if document.supersedes_document_version_id == document.document_version_id:
        raise ValueError("Un documento no puede sustituirse a si mismo")


def validate_document_acceptance_evidence(evidence: DocumentAcceptanceEvidence) -> None:
    for field_name, value in (("acceptance_id", evidence.acceptance_id), ("document_version_id", evidence.document_version_id), ("actor_reference", evidence.actor_reference), ("accepted_at", evidence.accepted_at), ("evidence_reference", evidence.evidence_reference)):
        if not str(value or "").strip():
            raise ValueError(f"DocumentAcceptanceEvidence requiere {field_name}")
    if evidence.revoked_at and not str(evidence.revocation_reason or "").strip():
        raise ValueError("Una revocacion requiere revocation_reason")
    if evidence.revoked_at and evidence.revoked_at < evidence.accepted_at:
        raise ValueError("revoked_at no puede ser anterior a accepted_at")


def is_acceptance_active(evidence: DocumentAcceptanceEvidence) -> bool:
    validate_document_acceptance_evidence(evidence)
    return evidence.revoked_at is None
